const NAV_LINKS = [
  { label: "AI factories", href: "#" },
  { label: "Products", href: "#" },
  { label: "Pricing", href: "#" },
  { label: "Company", href: "#" },
];

export default function Header() {
  const [mobileOpen, setMobileOpen] = useState(false);

  return (
    <header
      className="site-header"
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        zIndex: 1000,
        background: "var(--color-neutral-900)",
        borderBottom: "1px solid var(--color-neutral-800)",
      }}
    >
      <div
        style={{
          maxWidth: 1398,
          margin: "0 auto",
          padding: "0 15px",
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            height: 100,
          }}
        >
          {/* Logo */}
          <a href="#" aria-label="Lambda home">
            <LambdaLogo />
          </a>

          {/* Desktop nav */}
          <nav aria-label="Primary" className="hidden md:block">
            <ul
              style={{
                display: "flex",
                alignItems: "center",
                gap: 40,
                listStyle: "none",
                margin: 0,
                padding: 0,
              }}
            >
              {NAV_LINKS.map((link) => (
                <li key={link.label}>
                  <a
                    href={link.href}
                    className="font-mono uppercase"
                    style={{
                      fontSize: 14,
                      color: "var(--color-neutral-100)",
                      textDecoration: "none",
                      transition: "color var(--transition-snappy)",
                    }}
                  >
                    {link.label}
                  </a>
                </li>
              ))}
            </ul>
          </nav>

          {/* Right side: Log in + Get Started */}
          <div
            className="hidden md:flex"
            style={{
              alignItems: "center",
              gap: 0,
            }}
          >
            <a
              href="#"
              className="font-mono uppercase"
              style={{
                fontSize: 14,
                color: "var(--color-neutral-100)",
                textDecoration: "none",
                padding: "0 20px",
                height: 100,
                display: "flex",
                alignItems: "center",
              }}
            >
              Log in
            </a>
            <a
              href="#"
              className="font-mono uppercase"
              style={{
                fontSize: 14,
                color: "var(--color-neutral-900)",
                background: "var(--color-neutral-100)",
                textDecoration: "none",
                padding: "0 20px",
                height: 100,
                display: "flex",
                alignItems: "center",
              }}
            >
              Get started
            </a>
          </div>

          {/* Mobile hamburger */}
          <button
            type="button"
            className="flex md:hidden"
            aria-label={mobileOpen ? "Close menu" : "Open menu"}
            onClick={() => setMobileOpen(!mobileOpen)}
            style={{
              background: "none",
              border: "none",
              cursor: "pointer",
              padding: 10,
            }}
          >
            <svg
              width="24"
              height="24"
              viewBox="0 0 24 24"
              fill="none"
              stroke="var(--color-neutral-100)"
              strokeWidth="2"
            >
              {mobileOpen ? (
                <>
                  <line x1="4" y1="4" x2="20" y2="20" />
                  <line x1="20" y1="4" x2="4" y2="20" />
                </>
              ) : (
                <>
                  <line x1="3" y1="6" x2="21" y2="6" />
                  <line x1="3" y1="12" x2="21" y2="12" />
                  <line x1="3" y1="18" x2="21" y2="18" />
                </>
              )}
            </svg>
          </button>
        </div>
      </div>

      {/* Mobile menu */}
      {mobileOpen && (
        <nav
          className="header-mobile-menu"
          aria-label="Mobile navigation"
          style={{
            background: "var(--color-neutral-900)",
            borderTop: "1px solid var(--color-neutral-800)",
            padding: "20px 15px",
          }}
        >
          <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
            {NAV_LINKS.map((link) => (
              <li key={link.label} style={{ borderBottom: "1px solid var(--color-neutral-800)" }}>
                <a
                  href={link.href}
                  className="font-mono uppercase"
                  style={{
                    fontSize: 14,
                    color: "var(--color-neutral-100)",
                    textDecoration: "none",
                    display: "block",
                    padding: "16px 0",
                  }}
                >
                  {link.label}
                </a>
              </li>
            ))}
            <li style={{ marginTop: 20, display: "flex", flexDirection: "column", gap: 10 }}>
              <a
                href="#"
                className="font-mono uppercase"
                style={{
                  fontSize: 14,
                  color: "var(--color-neutral-100)",
                  textDecoration: "none",
                  textAlign: "center",
                  padding: "14px 20px",
                  border: "1px solid var(--color-neutral-800)",
                }}
              >
                Log in
              </a>
              <a
                href="#"
                className="font-mono uppercase"
                style={{
                  fontSize: 14,
                  color: "var(--color-neutral-900)",
                  background: "var(--color-neutral-100)",
                  textDecoration: "none",
                  textAlign: "center",
                  padding: "14px 20px",
                }}
              >
                Get started
              </a>
            </li>
          </ul>
        </nav>
      )}
    </header>
  );
}
